from itertools import permutations


def transform(grid):
    h = len(grid)
    w = max(map(len, grid))
    out = [list(row) + [1] * (w - len(row)) for row in grid]

    # Infer the repeating horizontal color cycle from intact neighboring cells.
    counts = Counter(v for r in range(3, h) for v in grid[r][3:] if v != 0)
    colors = sorted(v for v, n in counts.items() if n >= 3)
    if not colors:
        colors = sorted(counts)
    edges = Counter()
    for r in range(3, h):
        for c in range(3, len(grid[r]) - 1):
            a, b = grid[r][c], grid[r][c + 1]
            if a in colors and b in colors:
                edges[a, b] += 1

    # There are at most seven colors in these tasks. Select the cyclic order
    # which explains the most observed horizontal transitions.
    if len(colors) > 1:
        best_order, best_score = None, -1
        first = colors[0]
        for tail in permutations(colors[1:]):
            order = (first,) + tail
            score = sum(edges[order[i], order[(i + 1) % len(order)]] for i in range(len(order)))
            if score > best_score:
                best_order, best_score = order, score
        cycle = list(best_order)
    else:
        cycle = colors
    rank = {v: i for i, v in enumerate(cycle)}
    n = len(cycle)

    for r in range(h):
        for c in range(w):
            if c < len(grid[r]) and grid[r][c] != 0:
                continue
            if r < 2:
                out[r][c] = 1
            elif r == 2:
                out[r][c] = 1 if c < 2 else 4
            elif c < 2:
                out[r][c] = 1
            elif c == 2:
                out[r][c] = 4
            elif n:
                # Anchor on the nearest known cycle cell in the same row.
                anchors = [x for x in range(3, len(grid[r])) if grid[r][x] in rank]
                if anchors:
                    a = min(anchors, key=lambda x: abs(x - c))
                    out[r][c] = cycle[(rank[grid[r][a]] + c - a) % n]
                else:
                    # If the whole row is erased, extend the phase vertically.
                    above = next((rr for rr in range(r - 1, 2, -1)
                                  if any(v in rank for v in grid[rr][3:])), None)
                    if above is not None:
                        a = next(x for x in range(3, len(grid[above])) if grid[above][x] in rank)
                        out[r][c] = cycle[(rank[grid[above][a]] + c - a + r - above) % n]
    return out


